:root { --header-height:4rem; }
header { position:sticky; top:0; z-index:10; min-height:var(--header-height); background:var(--surface); border-bottom:1px solid var(--border); }
html { scroll-padding-top:calc(var(--header-height) + 1rem); }
[id] { scroll-margin-top:calc(var(--header-height) + 1rem); }
